WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY delivered_date DESC, id) AS rn FROM shipments QUALIFY rn = 1) SELECT CASE WHEN cost >= 78 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, MIN(cost) AS min_cost, STDDEV_SAMP(cost) AS cost_stddev, PERCENTILE_APPROX(cost, 0.9) AS cost_p90, APPROX_PERCENTILE(cost, 0.95) AS cost_p95, COUNT(*) FILTER (WHERE status = 'LOST') AS lost_rows FROM latest GROUP BY CASE WHEN cost >= 78 THEN 'LARGE' ELSE 'SMALL' END HAVING min_cost >= 0 ORDER BY cost_stddev NULLS FIRST;
